import path from "path"
import { findGitRepositories, RepoStatus } from "../../utils/multiRepoGit"

export class MultiRepoCheckpointManager {
	private workspaceRoot: string

	constructor(workspaceRoot: string) {
		this.workspaceRoot = workspaceRoot
	}

	/**
	 * Gets git repositories in the workspace.
	 */
	async getRepositories(): Promise<string[]> {
		return findGitRepositories(this.workspaceRoot)
	}

	/**
	 * Matches a file path to its closest containing git repository root.
	 * Returns null if no repository contains the file.
	 */
	findContainingRepo(filePath: string, repoRoots: string[]): string | null {
		// Normalize the file path, resolving relative paths against the workspace root.
		const normalizedFilePath = path.resolve(this.workspaceRoot, filePath)

		let bestMatch: string | null = null

		for (const repoRoot of repoRoots) {
			// Normalize the repo root, resolving relative paths against the workspace root.
			const normalizedRepoRoot = path.resolve(this.workspaceRoot, repoRoot)

			// The file is inside the repo if it equals the repo root or starts with
			// the repo root followed by a path separator.
			const isInside =
				normalizedFilePath === normalizedRepoRoot ||
				normalizedFilePath.startsWith(normalizedRepoRoot + path.sep)

			if (isInside && (bestMatch === null || normalizedRepoRoot.length > bestMatch.length)) {
				// Pick the most specific (longest) matching repo root.
				bestMatch = normalizedRepoRoot
			}
		}

		return bestMatch
	}

	/**
	 * Groups file paths by the git repository that contains them.
	 * Files not contained in any repository are grouped under "__untracked_root__".
	 */
	async groupFilesByRepo(filePaths: string[]): Promise<Map<string, string[]>> {
		const repoRoots = await this.getRepositories()
		const grouped = new Map<string, string[]>()

		for (const filePath of filePaths) {
			const repoRoot = this.findContainingRepo(filePath, repoRoots)
			const key = repoRoot ?? "__untracked_root__"

			const files = grouped.get(key) ?? []
			files.push(filePath)
			grouped.set(key, files)
		}

		return grouped
	}
}
